type BillingHistoryType string

const (
	BillingHistoryTypeAchFailure       BillingHistoryType = "ACHFailure"
	BillingHistoryTypeAdjustment       BillingHistoryType = "Adjustment"
	BillingHistoryTypeAttemptFailed    BillingHistoryType = "AttemptFailed"
	BillingHistoryTypeChargeback       BillingHistoryType = "Chargeback"
	BillingHistoryTypeCredit           BillingHistoryType = "Credit"
	BillingHistoryTypeCreditExpiration BillingHistoryType = "CreditExpiration"
	BillingHistoryTypeInvoice          BillingHistoryType = "Invoice"
	BillingHistoryTypePayment          BillingHistoryType = "Payment"
	BillingHistoryTypeRefund           BillingHistoryType = "Refund"
	BillingHistoryTypeReversal         BillingHistoryType = "Reversal"
)

func NewBillingHistoryTypeFromString(s string) (BillingHistoryType, error) {
	switch s {
	case "ACHFailure":
		return BillingHistoryTypeAchFailure, nil
	case "Adjustment":
		return BillingHistoryTypeAdjustment, nil
	case "AttemptFailed":
		return BillingHistoryTypeAttemptFailed, nil
	case "Chargeback":
		return BillingHistoryTypeChargeback, nil
	case "Credit":
		return BillingHistoryTypeCredit, nil
	case "CreditExpiration":
		return BillingHistoryTypeCreditExpiration, nil
	case "Invoice":
		return BillingHistoryTypeInvoice, nil
	case "Payment":
		return BillingHistoryTypePayment, nil
	case "Refund":
		return BillingHistoryTypeRefund, nil
	case "Reversal":
		return BillingHistoryTypeReversal, nil
	}
	var t BillingHistoryType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (b BillingHistoryType) Ptr() *BillingHistoryType {
	return &b
}

